//! Per-scale, oracle-sourced, width-deduplicated wide
//! transcendental constant table.
//!
//! GENERATED by `scripts/gen_const_table.py` from a flint/Arb
//! oracle: every golden mantissa below is `floor(const * 10^gp)`
//! resolved by `ball.floor().unique_fmpz()`, which yields a value
//! ONLY when the enclosing interval determines every retained
//! digit — so these digits are certified, not assumed correct at
//! some working precision. Do NOT edit by hand; re-run the script
//! and commit its output. This file is NOT produced at build time
//! — `build.rs` is untouched.
//!
//! Each constant ships ONE golden mantissa per band —
//! `floor(const * 10^(band_hi+1))` — and a `const fn` ([`cb_build`])
//! REBUILDS the per-scale table at compile time by dividing it down by
//! 10 one scale at a time. So the source carries ~hundreds of bytes per
//! constant, not the per-scale limbs, yet the compiled table (and the
//! runtime static lookup) is byte-identical to a literal one. Each
//! rebuilt entry is `floor(const * 10^scale)` as the narrowest-fit
//! little-endian `u64` slice plus a `round_up` bit = 1 iff the dropped
//! fractional tail is >= 1/2 (the most-significant dropped digit >= 5).
//! Every constant is irrational and positive, so the tail is never an
//! exact tie and never zero, and the six rounding modes derive exactly
//! from `(floor, round_up)`:
//!
//! | mode | result |
//! |------|--------|
//! | Trunc / Floor | `floor` |
//! | Ceiling / AwayFromZero | `floor + 1` |
//! | ZeroFiveUp | `floor + 1` iff `floor`'s last digit is 0 or 5 |
//! | HalfToEven / HalfAwayFromZero / HalfTowardZero | `floor + round_up` |
//!
//! The value is width-independent: an accessor zero-extends the
//! stored limbs into the caller's work integer (the high limbs stay
//! zero). The narrow band (`*_NARROW`, scales 0..=38) is ALWAYS
//! present — the public `DecimalConstants` trait on D18/D38 reads it
//! in every build (default / no_std included). The three wider bands
//! are feature-gated to match the tiers that can request them
//! (mirrors `src/types/consts/wide.rs`).

/// Scratch limb cap for the const-fn builders: the widest golden is
/// ln2 @ scale 5121 (~266 limbs); 280 leaves margin. A const-eval local
/// only — never in the binary.
const MAXK: usize = 280;

/// A compile-time-built per-scale constant band. `flat` holds every scale's
/// `floor(const * 10^scale)` as narrowest-fit little-endian limbs, packed
/// back-to-back; entry `i` (scale `lo + i`) is `flat[off[i] .. off[i]+len[i]]`
/// with round-up bit `bit[i]`. Built by [`cb_build`] from one golden mantissa.
pub(crate) struct ConstBand<const F: usize, const N: usize> {
    flat: [u64; F],
    off: [u32; N],
    len: [u16; N],
    bit: [u8; N],
}

/// Total narrowest-fit limb count over scales `lo..=hi`, divided down from
/// `golden = floor(const * 10^(hi+1))`. Sizes [`ConstBand`]'s `flat` exactly.
const fn cb_flat_len(golden: &[u64], lo: u32, hi: u32) -> usize {
    let mut buf = [0u64; MAXK];
    let mut blen = golden.len();
    let mut i = 0;
    while i < blen {
        buf[i] = golden[i];
        i += 1;
    }
    let mut total = 0usize;
    let mut scale = hi + 1;
    while scale > lo {
        let mut rem: u64 = 0;
        let mut j = blen;
        while j > 0 {
            j -= 1;
            let c = ((rem as u128) << 64) | (buf[j] as u128);
            buf[j] = (c / 10) as u64;
            rem = (c % 10) as u64;
        }
        while blen > 1 && buf[blen - 1] == 0 {
            blen -= 1;
        }
        total += blen;
        scale -= 1;
    }
    total
}

/// Build the band for scales `lo..=hi` by dividing `golden = floor(const *
/// 10^(hi+1))` down by 10 once per scale. Each division's remainder is the
/// most-significant dropped digit, so the round bit is `rem >= 5` — exact for
/// irrational constants (no tie); `floor(const*10^s) = floor(golden/10^(hi+1-s))`
/// is exact. Reproduces the former literal table bit-for-bit.
const fn cb_build<const F: usize, const N: usize>(
    golden: &[u64],
    lo: u32,
    hi: u32,
) -> ConstBand<F, N> {
    let mut b = ConstBand { flat: [0u64; F], off: [0u32; N], len: [0u16; N], bit: [0u8; N] };
    let mut buf = [0u64; MAXK];
    let mut blen = golden.len();
    let mut i = 0;
    while i < blen {
        buf[i] = golden[i];
        i += 1;
    }
    let mut scale = hi + 1;
    let mut cursor = 0usize;
    while scale > lo {
        let mut rem: u64 = 0;
        let mut j = blen;
        while j > 0 {
            j -= 1;
            let c = ((rem as u128) << 64) | (buf[j] as u128);
            buf[j] = (c / 10) as u64;
            rem = (c % 10) as u64;
        }
        while blen > 1 && buf[blen - 1] == 0 {
            blen -= 1;
        }
        let idx = (scale - 1 - lo) as usize;
        b.off[idx] = cursor as u32;
        b.len[idx] = blen as u16;
        b.bit[idx] = if rem >= 5 { 1 } else { 0 };
        let mut k = 0;
        while k < blen {
            b.flat[cursor + k] = buf[k];
            k += 1;
        }
        cursor += blen;
        scale -= 1;
    }
    b
}

/// The stored `(floor-limbs, round-up)` for entry `i` of a band — a `const fn`
/// so a const-scale caller folds to the one entry (and bakes through `const_n`).
/// `split_at` keeps it const-stable (range indexing is not yet const).
const fn cb_get<const F: usize, const N: usize>(
    b: &'static ConstBand<F, N>,
    i: usize,
) -> (&'static [u64], u8) {
    let o = b.off[i] as usize;
    let l = b.len[i] as usize;
    (b.flat.split_at(o).1.split_at(l).0, b.bit[i])
}

