/// `floor(pi * 10^scale)` limbs (little-endian, narrowest-fit)
/// plus the round-up bit, for the const working `scale`.
///
/// `const fn` so a caller keyed on the const-generic SCALE folds
/// to the single matching entry per monomorphisation — no runtime
/// search on the hot path. The band's per-scale `(limbs, round_up)`
/// is rebuilt at compile time from one golden mantissa ([`cb_build`]).
pub(crate) const fn pi_entry(scale: u32) -> (&'static [u64], u8) {
    // NARROW band (0..=38) is always present — the public
    // `DecimalConstants` trait on D18/D38 reads it in every build,
    // including default / no_std (no `_wide-support`).
    if (scale as usize) < 513 {
        return cb_get(&PI_NARROW, scale as usize);
    }
    #[cfg(feature = "_wide-support")]
    {
        if (scale as usize) < 513 {
            return cb_get(&PI_BASE, scale as usize);
        }
    }
    #[cfg(any(feature = "d462", feature = "d616", feature = "d924", feature = "d1232", feature = "x-wide", feature = "xx-wide"))]
    {
        let base_lo = 512 + 1;
        if scale >= base_lo {
            let idx = (scale - base_lo) as usize;
            if idx < 512 {
                return cb_get(&PI_XW, idx);
            }
        }
    }
    #[cfg(any(feature = "d924", feature = "d1232", feature = "xx-wide"))]
    {
        let xw_lo = 1024 + 1;
        if scale >= xw_lo {
            let idx = (scale - xw_lo) as usize;
            if idx < 1024 {
                return cb_get(&PI_XXW, idx);
            }
        }
    }
    panic!("const_table: pi scale out of generated range");
}

