use crate::int::types::traits::BigInt;
use crate::support::rounding::RoundingMode;

/// Builds the work integer `W` holding `floor(const * 10^scale)`
/// from a narrow little-endian `limbs` slice by DIRECT limb injection:
/// a little-endian u64 limb slice IS the value (`Σ limbs[i]·2^(64·i)`),
/// so the low `min(len, W::LIMBS)` limbs are copied and the rest stay
/// zero — bit-identical to the previous high-to-low Horner fold
/// (`acc = (acc << 64) | limb`), which kept the same low limbs but paid
/// a full-`W`-width shift + OR + rebuild PER SOURCE LIMB (O(len · W)
/// instead of O(len)). The fold was a measured hot frame in the wide
/// `ln`/`exp` shells, where every `pow10`/`ln2`/`pi` lookup runs this on
/// a multi-limb entry at a 32-limb-plus work integer.
#[inline]
pub(crate) fn limbs_to_w<W: BigInt>(limbs: &[u64]) -> W {
    W::from_mag_sign_u64(limbs, false)
}

/// Applies `mode` to a `(floor-limbs, round_up)` table entry,
/// returning the correctly-rounded constant in the work integer `W`.
///
/// The constants are irrational + positive, so the dropped tail is
/// never an exact tie and never zero. Hence: Trunc / Floor keep the
/// floor; Ceiling and AwayFromZero always bump (`+1`); ZeroFiveUp
/// bumps only when the floor's last decimal digit is `0` or `5`; the
/// three half-modes all reduce to round-to-nearest = `floor +
/// round_up`. This reproduces a correct rounding of the oracle value
/// under every mode.
#[inline]
fn round_entry<W: BigInt>(limbs: &[u64], round_up: u8, mode: RoundingMode) -> W {
    let floor = limbs_to_w::<W>(limbs);
    let bump = match mode {
        RoundingMode::Trunc | RoundingMode::Floor => false,
        RoundingMode::Ceiling => true,
        RoundingMode::HalfToEven
        | RoundingMode::HalfAwayFromZero
        | RoundingMode::HalfTowardZero => round_up != 0,
        // The tail is never zero, and the value is positive, so
        // away-from-zero always lifts — as Ceiling does.
        RoundingMode::AwayFromZero => true,
        // `limbs` IS the floor value (zero-extended, never truncated),
        // so its last decimal digit is the pivot.
        RoundingMode::ZeroFiveUp => {
            matches!(crate::support::rounding::limbs_mod_10(limbs), 0 | 5)
        }
    };
    if bump { floor.wrapping_add(W::ONE) } else { floor }
}

/// Like [`round_entry`], but returns `None` when the value does
/// not fit the SIGNED positive range of the work/storage integer
/// `W` (i.e. it would exceed `Int::<W::LIMBS>::MAX`). Used by the
/// PUBLIC constant accessors, where a constant requested at a
/// scale too large for the type's storage must surface an overflow
/// (the caller panics with an "out of storage range" message),
/// not silently wrap. The constants are positive and the limbs are
/// narrowest-fit, so the fit test is purely structural:
///
///   * more limbs than `W` holds            -> overflow;
///   * exactly `W::LIMBS` limbs and the top limb has its high bit
///     set (>= 2^63) -> the magnitude reaches into `W`'s sign bit
///     -> overflow (the `+1` round-up bump cannot clear an already-
///     set top bit, so no false negative);
///   * otherwise it fits, and the rounded fold is exact.
///
/// The INTERNAL kernel path (`*_by_scale` / `*_by_working_scale`) does NOT use
/// this — it folds into a wide WORK integer where the value always
/// fits and must never panic.
#[inline]
fn round_entry_checked<W: BigInt>(
    limbs: &[u64],
    round_up: u8,
    mode: RoundingMode,
) -> Option<W> {
    let n = W::LIMBS;
    if limbs.len() > n {
        return None;
    }
    if limbs.len() == n && (limbs[n - 1] & 0x8000_0000_0000_0000) != 0 {
        return None;
    }
    Some(round_entry::<W>(limbs, round_up, mode))
}

/// `pi` at the CONST working `scale`, correctly rounded
/// under `mode`, in the work integer `W`. **The norm.**
///
/// The scale -> entry lookup ([`pi_entry`]) is a `const fn`; when
/// `scale` is the const-generic working scale of the
/// monomorphisation it folds to the one matching `(&'static
/// [u64], round_up)`, so the only runtime work is the cheap
/// fixed-count zero-extend into `W` (which LLVM further folds
/// against the const limbs). No runtime search, no divide. The
/// hot (non-Ziv) path uses this.
#[inline]
pub(crate) fn pi_by_scale<W: BigInt>(scale: u32, mode: RoundingMode) -> W {
    let (limbs, round_up) = pi_entry(scale);
    round_entry::<W>(limbs, round_up, mode)
}

