#[cfg(test)]
mod tests {
    use super::*;
    use crate::int::types::Int;
    use crate::support::rounding::RoundingMode::*;

    /// The six modes derive correctly from the stored (floor,
    /// round_up) pair: Trunc=Floor=floor, Ceiling=floor+1, and the
    /// three half-modes coincide at floor+round_up (no ties for
    /// irrationals). Spot-checked against `pi` at a few scales.
    #[test]
    fn modes_derive_from_floor_and_roundbit() {
        // pi = 3.14159265358979323846...; at scale 4 -> 31415.9..,
        // floor 31415, tail .9 >= .5 -> round_up = 1.
        let f: Int<3> = limbs_to_w(&[31415]);
        assert_eq!(pi_by_scale::<Int<3>>(4, Trunc), f);
        assert_eq!(pi_by_scale::<Int<3>>(4, Floor), f);
        assert_eq!(pi_by_scale::<Int<3>>(4, Ceiling), f.wrapping_add(Int::<3>::ONE));
        let up = f.wrapping_add(Int::<3>::ONE);
        assert_eq!(pi_by_scale::<Int<3>>(4, HalfToEven), up);
        assert_eq!(pi_by_scale::<Int<3>>(4, HalfAwayFromZero), up);
        assert_eq!(pi_by_scale::<Int<3>>(4, HalfTowardZero), up);
        // scale 5 -> 314159.26.., floor 314159, tail .26 < .5 ->
        // round_up = 0; all three half-modes keep the floor.
        let f5: Int<3> = limbs_to_w(&[314159]);
        assert_eq!(pi_by_scale::<Int<3>>(5, HalfToEven), f5);
        assert_eq!(pi_by_scale::<Int<3>>(5, Ceiling), f5.wrapping_add(Int::<3>::ONE));
    }

    /// `by_scale` and `by_working_scale` return identical values for the same
    /// scale (they differ only in const-fold behaviour, not value).
    /// Uses an `Int<16>` work integer, which only exists in a
    /// `_wide-support` build, so the test is gated to that build (a
    /// narrow-only build has no work integer this wide to exercise).
    #[cfg(feature = "_wide-support")]
    #[test]
    fn by_scale_eq_by_working_scale() {
        for scale in [0u32, 1, 17, 18, 19, 30, 38, 86] {
            for mode in [HalfToEven, Trunc, Ceiling, Floor, HalfAwayFromZero, HalfTowardZero] {
                assert_eq!(
                    pi_by_scale::<Int<16>>(scale, mode),
                    pi_by_working_scale::<Int<16>>(scale, mode),
                );
                assert_eq!(
                    ln2_by_scale::<Int<16>>(scale, mode),
                    ln2_by_working_scale::<Int<16>>(scale, mode),
                );
            }
        }
    }

    /// Width-independence: the same scale gives the same value
    /// (zero-extended) in different work-int widths. Exercises
    /// `Int<16>` / `Int<32>` work integers (and `resize_to` between
    /// them), which only exist in a `_wide-support` build — so the
    /// test is gated there. The always-present narrow band is
    /// covered by `modes_derive_from_floor_and_roundbit` above.
    #[cfg(feature = "_wide-support")]
    #[test]
    fn value_is_width_independent() {
        for scale in [0u32, 5, 17, 18, 30, 38, 50] {
            let narrow = pi_by_scale::<Int<16>>(scale, HalfToEven);
            let wide = pi_by_scale::<Int<32>>(scale, HalfToEven);
            assert_eq!(narrow, wide.resize_to::<Int<16>>());
        }
    }
}

/// A compile-time-built `10^exp` band (exact — no round bit). `flat` packs every
/// exponent's narrowest-fit little-endian limbs; entry `i` (exp `lo + i`) is
/// `flat[off[i] .. off[i]+len[i]]`. Built by [`p10_build`] from `1` by ×10.
pub(crate) struct Pow10Band<const F: usize, const N: usize> {
    flat: [u64; F],
    off: [u32; N],
    len: [u16; N],
}

/// Total narrowest-fit limb count over `10^lo ..= 10^hi`, sizing the flat array.
const fn p10_flat_len(lo: u32, hi: u32) -> usize {
    let mut buf = [0u64; MAXK];
    buf[0] = 1;
    let mut blen = 1usize;
    let mut total = 0usize;
    if lo == 0 {
        total += 1;
    }
    let mut e = 1u32;
    while e <= hi {
        let mut carry: u64 = 0;
        let mut i = 0;
        while i < blen {
            let v = (buf[i] as u128) * 10 + carry as u128;
            buf[i] = v as u64;
            carry = (v >> 64) as u64;
            i += 1;
        }
        if carry > 0 {
            buf[blen] = carry;
            blen += 1;
        }
        if e >= lo {
            total += blen;
        }
        e += 1;
    }
    total
}

/// Build `10^lo ..= 10^hi` by repeated ×10 from 1. `10^exp` is exact, so there
/// is no round bit. Reproduces the former literal POW10 table bit-for-bit.
const fn p10_build<const F: usize, const N: usize>(lo: u32, hi: u32) -> Pow10Band<F, N> {
    let mut b = Pow10Band { flat: [0u64; F], off: [0u32; N], len: [0u16; N] };
    let mut buf = [0u64; MAXK];
    buf[0] = 1;
    let mut blen = 1usize;
    let mut cursor = 0usize;
    if lo == 0 {
        b.off[0] = 0;
        b.len[0] = 1;
        b.flat[0] = 1;
        cursor = 1;
    }
    let mut e = 1u32;
    while e <= hi {
        let mut carry: u64 = 0;
        let mut i = 0;
        while i < blen {
            let v = (buf[i] as u128) * 10 + carry as u128;
            buf[i] = v as u64;
            carry = (v >> 64) as u64;
            i += 1;
        }
        if carry > 0 {
            buf[blen] = carry;
            blen += 1;
        }
        if e >= lo {
            let idx = (e - lo) as usize;
            b.off[idx] = cursor as u32;
            b.len[idx] = blen as u16;
            let mut k = 0;
            while k < blen {
                b.flat[cursor + k] = buf[k];
                k += 1;
            }
            cursor += blen;
        }
        e += 1;
    }
    b
}

/// Limbs of `10^(lo+i)` for entry `i` — a `const fn` so a const `exp` folds.
const fn p10_get<const F: usize, const N: usize>(
    b: &'static Pow10Band<F, N>,
    i: usize,
) -> &'static [u64] {
    let o = b.off[i] as usize;
    let l = b.len[i] as usize;
    b.flat.split_at(o).1.split_at(l).0
}

const POW10_NARROW_F: usize = p10_flat_len(0, 512);
static POW10_NARROW: Pow10Band<POW10_NARROW_F, 513> = p10_build(0, 512);

#[cfg(feature = "_wide-support")]
const POW10_BASE_F: usize = p10_flat_len(0, 1280);
#[cfg(feature = "_wide-support")]
static POW10_BASE: Pow10Band<POW10_BASE_F, 1281> = p10_build(0, 1280);

#[cfg(any(feature = "d462", feature = "d616", feature = "d924", feature = "d1232", feature = "x-wide", feature = "xx-wide"))]
const POW10_XW_F: usize = p10_flat_len(1281, 2560);
#[cfg(any(feature = "d462", feature = "d616", feature = "d924", feature = "d1232", feature = "x-wide", feature = "xx-wide"))]
static POW10_XW: Pow10Band<POW10_XW_F, 1280> = p10_build(1281, 2560);

#[cfg(any(feature = "d924", feature = "d1232", feature = "xx-wide"))]
const POW10_XXW_F: usize = p10_flat_len(2561, 5120);
#[cfg(any(feature = "d924", feature = "d1232", feature = "xx-wide"))]
static POW10_XXW: Pow10Band<POW10_XXW_F, 2560> = p10_build(2561, 5120);

/// Limbs (little-endian) of `10^exp` if `exp` is within a generated POW10
/// band, else `None`. Bands are feature-gated; the always-present NARROW
/// band covers the default / no_std build. `const fn` so a const `exp`
/// folds to the matching entry. The per-exp limbs are rebuilt at compile
/// time ([`p10_build`]), not shipped as literals.
#[inline]
const fn pow10_entry(exp: u32) -> Option<&'static [u64]> {
    if (exp as usize) < 513 {
        return Some(p10_get(&POW10_NARROW, exp as usize));
    }
    #[cfg(feature = "_wide-support")]
    {
        if (exp as usize) < 1281 {
            return Some(p10_get(&POW10_BASE, exp as usize));
        }
    }
    #[cfg(any(feature = "d462", feature = "d616", feature = "d924", feature = "d1232", feature = "x-wide", feature = "xx-wide"))]
    {
        let base_lo = 1280 + 1;
        if exp >= base_lo {
            let idx = (exp - base_lo) as usize;
            if idx < 1280 {
                return Some(p10_get(&POW10_XW, idx));
            }
        }
    }
    #[cfg(any(feature = "d924", feature = "d1232", feature = "xx-wide"))]
    {
        let xw_lo = 2560 + 1;
        if exp >= xw_lo {
            let idx = (exp - xw_lo) as usize;
            if idx < 2560 {
                return Some(p10_get(&POW10_XXW, idx));
            }
        }
    }
    None
}

/// Raw little-endian u64 limbs of `10^exp` from the generated POW10 table,
/// or `None` beyond the (feature-gated) table range. The untyped sibling of
/// [`pow10_in`] — for callers that need the limbs directly in a `[u64]`
/// scratch (e.g. the Newton-reciprocal `precompute`, which otherwise rebuilds
/// `10^scale` with an O(scale²) ×10 chain per call). `const fn` so a const
/// `exp` folds to the entry.
#[inline]
pub(crate) const fn pow10_limbs(exp: u32) -> Option<&'static [u64]> {
    pow10_entry(exp)
}

// `10^exp` in a work integer is the `pow10` POLICY now: `super::pow10::dispatch`
// (table-first, square-and-multiply fallback). The raw-limbs Table primitive is
// `pow10_limbs` above; `limbs_to_w` is the Table-arm zero-extend it uses.

